"""Real frontend regressions for fullscreen welcome, resize and explicit Forge."""
import argparse,json,sys,tempfile,threading
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from backend.server import Application,LumenServer
from playwright.sync_api import sync_playwright,expect

def main():
 parser=argparse.ArgumentParser();parser.add_argument('--output',required=True,type=Path);out=parser.parse_args().output;out.mkdir(parents=True,exist_ok=True);checks=[];errors=[]
 def passed(name):checks.append(name);print('PASS',name,flush=True)
 with tempfile.TemporaryDirectory(prefix='zenit-correction-') as tmp:
  base=Path(tmp);ws=base/'project';ws.mkdir();(ws/'main.js').write_text('const value=41;\nconsole.log(value+1);\n');(ws/'other.py').write_text('print("hola ñ")\n',encoding='utf-8')
  app=Application(ROOT,ws,data_dir=base/'profile');app.workspace.trusted=True;app.features.studio.update({'onboarded':True,'displayName':'Usuario ñ'});app.features.prefs.update({'hacker.enabled':True,'appearance.motion':True,'general.showWelcome':True})
  server=LumenServer(0,app);threading.Thread(target=server.serve_forever,daemon=True).start()
  try:
   with sync_playwright() as pw:
    browser=pw.chromium.launch(channel='msedge',headless=True,args=['--use-angle=swiftshader','--enable-unsafe-swiftshader']);page=browser.new_page(viewport={'width':1672,'height':917});page.on('pageerror',lambda e:errors.append(str(e)))
    def inject(route):
     response=route.fetch();route.fulfill(response=response,body=response.text()+'\nwindow.__qa={get studio(){return studio},get dock(){return dock},get editor(){return editor},get platform(){return platformUI},get desktop(){return desktopUI},openFile,perform};')
    page.route('**/src/app.js',inject);page.goto(f'http://127.0.0.1:{server.server_port}?diagnostics=1',wait_until='domcontentloaded');page.wait_for_function('window.lumen?.ready');page.wait_for_function('document.querySelector(".welcome-scene .gpu-ready")')
    assert page.evaluate('document.querySelector("canvas[data-glass=welcome]").dataset.geometry==="blender-double-wall"');assert page.evaluate('(()=>{const r=document.querySelector(".welcome-sheet").getBoundingClientRect();return r.x===0&&r.y===0&&r.width===innerWidth&&r.height===innerHeight})()');page.screenshot(path=str(out/'welcome-fullscreen.png'));passed('Welcome covers the whole viewport without a nested card');page.mouse.move(60,100);page.wait_for_function('document.querySelector("#lumen-home").style.getPropertyValue("--welcome-x")!==""');assert page.evaluate('Math.abs(parseFloat(document.querySelector("#lumen-home").style.getPropertyValue("--welcome-x")))<=4');passed('Welcome depth responds to pointer input within a four-pixel bound')
    page.evaluate('window.__welcomeCanvas=document.querySelector("canvas[data-glass=welcome]")')
    for theme in ('dark','forest'):
     page.evaluate('async theme=>await __qa.platform.savePreference("appearance.theme",theme)',theme)
     assert page.evaluate('document.querySelector("canvas[data-glass=welcome]")===__welcomeCanvas')
     assert page.evaluate('getComputedStyle(document.querySelector(".welcome-landscape")).filter.includes("brightness(0.42)")')
     assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path=str(out/f'welcome-{theme}.png'))
    page.evaluate('async()=>await __qa.platform.savePreference("appearance.theme","day")');passed('Dark and Forest welcome use a subdued landscape without replacing the animated canvas')
    page.locator('.welcome-profile').click();expect(page.locator('.profile-activity-identity')).to_contain_text('Usuario ñ');expect(page.locator('.profile-activity-list')).to_contain_text('Todavía no');page.keyboard.press('Escape');expect(page.locator('#lumen-home')).to_be_visible();passed('One click opens the real local profile; a fresh profile invents no activity')
    times=page.evaluate('async()=>{const canvas=document.querySelector("canvas[data-glass=welcome]"),engine=BABYLON.EngineStore.Instances.find(e=>e.getRenderingCanvas()===canvas),material=engine.scenes[0].getMaterialByName("iridescence"),a=material._floats.time;await new Promise(r=>setTimeout(r,900));return {before:a,after:material._floats.time,loops:engine._activeRenderLoops.length}}');assert times['after']>times['before'] and times['loops']==1,times;passed('The actual Babylon shader advances with one render loop')
    assert page.evaluate('(()=>{const c=document.querySelector("canvas[data-glass=welcome]");return BABYLON.EngineStore.Instances.find(e=>e.getRenderingCanvas()===c).maxFPS===60})()');page.emulate_media(reduced_motion='reduce');page.wait_for_function('(()=>{const c=document.querySelector("canvas[data-glass=welcome]");return BABYLON.EngineStore.Instances.find(e=>e.getRenderingCanvas()===c)._activeRenderLoops.length===0})()');page.emulate_media(reduced_motion='no-preference');page.wait_for_function('(()=>{const c=document.querySelector("canvas[data-glass=welcome]");return BABYLON.EngineStore.Instances.find(e=>e.getRenderingCanvas()===c)._activeRenderLoops.length===1})()');assert page.evaluate('getComputedStyle(document.querySelector(".welcome-landscape")).animationName==="welcome-horizon"');page.emulate_media(reduced_motion='reduce');assert page.evaluate('getComputedStyle(document.querySelector(".welcome-landscape")).animationName==="none"');page.emulate_media(reduced_motion='no-preference');passed('The render rate is bounded and reduced-motion stops the loop and landscape animation')
    page.evaluate('(()=>{const c=document.querySelector("canvas[data-glass=welcome]"),e=BABYLON.EngineStore.Instances.find(e=>e.getRenderingCanvas()===c);window.__qaLost=e._gl.getExtension("WEBGL_lose_context");__qaLost.loseContext()})()');page.wait_for_function('!document.querySelector("canvas[data-glass=welcome]").parentElement.classList.contains("gpu-ready")');page.evaluate('__qaLost.restoreContext()');page.wait_for_function('document.querySelector("canvas[data-glass=welcome]").parentElement.classList.contains("gpu-ready")');passed('A lost WebGL context recovers on the same canvas')
    page.keyboard.press('Escape');page.evaluate('async()=>{await __qa.openFile("main.js");await __qa.openFile("other.py")}');page.wait_for_function('document.querySelector("canvas[data-glass=welcome]").getClientRects().length===0')
    assert page.evaluate('(()=>{const c=document.querySelector("canvas[data-glass=welcome]");return BABYLON.EngineStore.Instances.find(e=>e.getRenderingCanvas()===c)._activeRenderLoops.length===0})()');assert page.evaluate('getComputedStyle(document.querySelector(".welcome-landscape")).animationPlayState==="paused"');passed('The welcome canvas is retained and both scene and landscape stop while hidden')
    retained=page.evaluate(r'()=>{const node=document.querySelector("[data-tab=\"other.py\"]"),original=__qa.editor.getValue();__qa.editor.insertText("print(2)\n",true);const dirtySame=node===document.querySelector("[data-tab=\"other.py\"]");__qa.editor.insertText(original,true);__qa.editor.activate("main.js");__qa.editor.activate("other.py");return dirtySame&&node===document.querySelector("[data-tab=\"other.py\"]")}');assert retained;passed('File tab nodes survive edits and active-file changes without remounting')
    expect(page.locator('.forge-dashboard')).to_be_hidden();page.locator('[data-terminal=terminal]').click();expect(page.locator('.forge-dashboard')).to_be_hidden();passed('Opening Terminal does not enable Forge even with the old saved preference')
    for side,selector,axis,delta in [('bottom','#terminal-resizer','y',-80),('left','#tree-resizer','x',35),('right','#ai-resizer','x',-35)]:
     handle=page.locator(selector);box=handle.bounding_box();x=box['x']+box['width']/2;y=box['y']+box['height']/2
     assert page.evaluate('([x,y,id])=>document.elementFromPoint(x,y)?.closest(".dock-resizer")?.id===id',[x,y,selector[1:]]),side
     before=page.locator('#dock-'+side).bounding_box();page.mouse.move(x,y);page.mouse.down();page.mouse.move(x+(delta if axis=='x' else 0),y+(delta if axis=='y' else 0),steps=6);page.mouse.up();after=page.locator('#dock-'+side).bounding_box();dimension='height' if axis=='y' else 'width';assert abs(after[dimension]-before[dimension])>20,(side,before,after)
    page.screenshot(path=str(out/'editor-terminal-resized.png'));passed('All three separators receive pointer input and resize their actual panels')
    # Explicit transport fixture: this checks UI contracts, not model quality.
    requests=[];responses={}
    def ai_start(route):
     body=route.request.post_data_json;requests.append(body);key='fixture-'+str(len(requests));responses[key]='```python\n# sugerencia de prueba\n```' if 'continuación inmediata' in body['question'] else 'Hallazgo de prueba para el búfer actual. Línea 1: revisa la entrada. Línea 999: referencia inválida.';route.fulfill(json={'id':key})
    page.route('**/api/platform/ai/start',ai_start);page.route('**/api/platform/ai/job?*',lambda route:route.fulfill(json={'offset':1,'delta':responses[route.request.url.split('id=')[1].split('&')[0]],'done':True}));page.route('**/api/platform/ai/cancel',lambda route:route.fulfill(json={'cancelled':True}))
    before=page.evaluate('__qa.editor.getValue()');page.evaluate('()=>{const p=__qa.platform;p.prefs["ai.provider"]="fixture";p.prefs["ai.model"]="fixture-model";p.companion.session.minInterval=0;p.companion.session.idleMs=100;__qa.editor.view.setPosition({lineNumber:2,column:1});}');page.locator('#ai-input').fill('Ayúdame en tiempo real mientras escribo');page.locator('#ai-form .send-button').click();page.get_by_role('button',name='Activar ayuda',exact=True).click();expect(page.locator('.melody-companion-card pre')).to_contain_text('Hallazgo de prueba');assert requests[0]['content']==before;assert page.evaluate('__qa.editor.getValue()')==before;expect(page.locator('#assistant-hero')).to_be_hidden();expect(page.locator('#ai-actions')).to_be_hidden();assert page.evaluate('__qa.editor.view.getModel().getAllDecorations().some(d=>d.options.linesDecorationsClassName==="melody-advice-mark")');passed('Active Melody advice replaces the welcome cards and adds a revision-bound Monaco hint')
    for width,height in [(1280,720),(1366,768)]:
     page.set_viewport_size({'width':width,'height':height});page.wait_for_function('(()=>{const form=document.querySelector("#ai-form").getBoundingClientRect(),panel=document.querySelector("#assistant-panel").getBoundingClientRect();return form.bottom<=panel.bottom&&document.documentElement.scrollWidth<=innerWidth})()')
    page.set_viewport_size({'width':1672,'height':917});passed('An active advice panel keeps the composer visible at 1280x720 and 1366x768')
    expect(page.locator('.companion-references button')).to_have_count(1);page.locator('.companion-references button').click();assert page.evaluate('__qa.editor.view.getPosition().lineNumber')==1;assert page.evaluate('__qa.editor.getValue()')==before;passed('Melody references navigate to actual bounded lines without editing the buffer')
    page.evaluate('()=>__qa.editor.view.setSelection(new monaco.Range(1,1,1,8))');page.locator('[data-companion-focus=explain]').click();expect(page.locator('[data-companion-focus=explain]')).to_have_attribute('aria-pressed','true');page.wait_for_function('document.querySelector(".melody-companion-card").dataset.state==="ready"');assert 'didáctica' in requests[-1]['question'] and 'Selección actual' in requests[-1]['question'];page.evaluate('()=>__qa.editor.view.setPosition({lineNumber:2,column:1})');passed('Explain mode sends the real selection to the authorised provider (fixture transport)')
    page.locator('[data-companion=predict]').click();expect(page.locator('.monaco-editor .view-lines')).to_contain_text('sugerencia de prueba');page.screenshot(path=str(out/'melody-companion.png'));assert page.evaluate('__qa.editor.getValue()')==before;page.keyboard.press('Tab');assert page.evaluate('__qa.editor.getValue().includes("# sugerencia de prueba")');assert page.evaluate('!__qa.editor.view.getModel().getAllDecorations().some(d=>d.options.linesDecorationsClassName==="melody-advice-mark")');assert (ws/'other.py').read_text(encoding='utf-8')==before;page.locator('.melody-companion-card header button').click();page.evaluate('(text)=>__qa.editor.insertText(text,true)',before);passed('Melody advice remains read-only and a real Monaco inline suggestion requires explicit acceptance (fixture transport)')
    page.evaluate('__qa.studio.home()');page.locator('.welcome-profile').click();expect(page.locator('.profile-activity-file')).to_have_count(2);page.evaluate('async()=>await Promise.all(document.querySelector("#modal").getAnimations().map(a=>a.finished.catch(()=>{})))');page.screenshot(path=str(out/'profile-activity.png'));page.locator('.profile-activity-file').filter(has_text='main.js').click();page.wait_for_function('window.lumen.activeFile==="main.js"');passed('Recent files show real timestamps and reopen the selected buffer')
    page.evaluate('__qa.studio.home()');page.locator('[data-action=new-project]').click();page.locator('#project-parent').fill(str(base));page.locator('#project-name').fill('Nuevo ñ');page.locator('#new-project-form button[type=submit]').click();page.wait_for_function('document.documentElement.dataset.screen==="studio"');assert (base/'Nuevo ñ').is_dir();assert app.workspace.root==(base/'Nuevo ñ').resolve();passed('New project creates and opens a real empty folder')
    assert not errors,errors;passed('No uncaught JavaScript errors')
    browser.close();(out/'checks.json').write_text(json.dumps({'checks':checks,'errors':errors,'animation':times,'aiTransport':'Explicit fixture, not an external model evaluation.'},indent=2),encoding='utf-8')
  finally:server.shutdown();server.server_close();app.features.shutdown();app.runner.shutdown()
if __name__=='__main__':main()
